def count_ways(n, k):
    if k == 1:
        return pow(n - 1, n - 1, MOD)

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if i > j:
                dp[i][j] = (dp[i][j] + dp[i - 1][j] * (i - j)) % MOD

    result = dp[n][k]
    for i in range(1, k + 1):
        result = (result * pow(i, n - k, MOD)) % MOD

    return result

