def count_ways(n, k):
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, j):
        if i == 0:
            return 1 if j == 0 else 0
        if j > k:
            return 0

        res = 0
        for x in range(1, n + 1):
            if x != i + 1 and (j == 0 or dp(i - 1, j - 1) > 0):
                res = (res + dp(i - 1, j - int(x == 1))) % MOD
        return res

    return dp(n, k)

